#!/bin/sh
# TLS 1.3 client-certificate and SPKI-pinning interop regression.
# The client credential is generated by brick, persisted in factotum's
# encrypted keyfile, and reloaded in a fresh emulator for every case.

set -u

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
. "$(dirname "$0")/common.sh"

[ -x "$EMU" ] || { echo "SKIP: emu not found at $EMU"; exit 77; }
[ -f "$ROOT/dis/tests/tlspinclient.dis" ] || { echo "SKIP: tlspinclient.dis not built"; exit 77; }
command -v openssl >/dev/null 2>&1 || { echo "SKIP: no openssl"; exit 77; }
command -v python3 >/dev/null 2>&1 || { echo "SKIP: no python3"; exit 77; }

REL=tmp/tls-clientauth.$$
STATE="$ROOT/$REL"
PORT=$((20000 + $$ % 20000))
fails=0
sp=

cleanup() {
    [ -n "$sp" ] && kill "$sp" 2>/dev/null
    rm -rf "$STATE"
}
trap cleanup EXIT INT TERM
mkdir -p "$STATE"

set +e
KEYOUT=$(with_timeout 45 "$EMU" -c0 -r"$ROOT" /dis/sh.dis \
    /tests/brick/tls_keygen.sh /$REL 2>&1)
keyrc=$?
set -e
if ! emu_timeout_ok "$keyrc" || ! printf '%s\n' "$KEYOUT" | grep -q TLS-KEYGEN-DONE; then
    printf '%s\n' "$KEYOUT"
    echo "FAIL: brick/factotum key generation"
    exit 1
fi

openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:P-256 \
    -keyout "$STATE/sk.pem" -out "$STATE/sc.pem" -days 1 -nodes \
    -subj "/CN=nobody-checks-this" >/dev/null 2>&1
PIN=$(openssl x509 -in "$STATE/sc.pem" -noout -pubkey |
    openssl pkey -pubin -outform DER |
    openssl dgst -sha256 -r | awk '{print $1}')
BADPIN=$(printf '%s\n' "$PIN" | tr '0-9a-f' '1-9a-f0')
openssl x509 -inform DER -in "$STATE/k/client.crt" -out "$STATE/cc.pem"
openssl x509 -in "$STATE/sc.pem" -outform DER -out "$STATE/sc.der"

# Make malformed certificates around the exact SPKI boundary.  These are fed
# to TLS's exported pin verifier, which is the same function the handshake
# calls before CertificateVerify.  The cases exercise the hand-written raw-DER
# locator and X509's decoded key view together.
mkdir -p "$STATE/malformed"
python3 - "$STATE/sc.der" "$STATE/malformed" <<'PY'
import pathlib
import sys

src = bytearray(pathlib.Path(sys.argv[1]).read_bytes())
out = pathlib.Path(sys.argv[2])

def tlv(a, off):
    if off + 2 > len(a):
        raise ValueError("short tlv")
    tag = a[off]
    n = a[off + 1]
    h = 2
    if n & 0x80:
        k = n & 0x7f
        if not k or off + 2 + k > len(a):
            raise ValueError("bad length")
        n = int.from_bytes(a[off + 2:off + 2 + k], "big")
        h += k
    if off + h + n > len(a):
        raise ValueError("past end")
    return tag, h, n

tag, oh, olen = tlv(src, 0)
assert tag == 0x30 and oh + olen == len(src)
tbs = oh
tag, th, tlen = tlv(src, tbs)
assert tag == 0x30
off = tbs + th
tag, h, n = tlv(src, off)
if tag == 0xa0:
    off += h + n
    tag, h, n = tlv(src, off)
for _ in range(5):
    off += h + n
    tag, h, n = tlv(src, off)
spki = off
assert tag == 0x30
alg = spki + h
_, ah, an = tlv(src, alg)
bit = alg + ah + an
btag, bh, bn = tlv(src, bit)
assert btag == 0x03 and bn > 1

(out / "truncated.der").write_bytes(src[:-1])
(out / "trailing.der").write_bytes(src + b"\x00")

# BER-valid but non-DER outer length with one redundant leading zero.
k = oh - 2
assert k > 0
nonminimal = bytearray([0x30, 0x80 | (k + 1), 0])
nonminimal += src[2:2 + k]
nonminimal += src[oh:]
(out / "nonminimal-length.der").write_bytes(nonminimal)

wrongtag = bytearray(src)
wrongtag[spki] = 0x31
(out / "wrong-spki-tag.der").write_bytes(wrongtag)

unused = bytearray(src)
unused[bit + bh] = 1
(out / "nonzero-unused-bits.der").write_bytes(unused)
PY

pin_case() {
    name=$1
    want=$2
    cert=$3
    set +e
    with_timeout 30 "$EMU" -c0 -r"$ROOT" /dis/sh.dis \
        /tests/brick/tls_pincheck.sh "$cert" "$PIN" \
        >"$STATE/pin.out" 2>&1
    pinrc=$?
    set -e
    if emu_timeout_ok "$pinrc" && grep -q "^$want" "$STATE/pin.out"; then
        echo "PASS: $name ($want)"
    else
        echo "FAIL: $name (want $want, emulator $pinrc)"
        sed 's/^/    /' "$STATE/pin.out" 2>/dev/null
        fails=$((fails + 1))
    fi
}

pin_case pin-valid PIN-OK /$REL/sc.der
for malformed in truncated trailing nonminimal-length wrong-spki-tag nonzero-unused-bits; do
    pin_case "pin-malformed-$malformed" PIN-FAIL "/$REL/malformed/$malformed.der"
done

# case_run name expected profile cert pin [s_server options]
case_run() {
    name=$1
    expect=$2
    profile=$3
    cert=$4
    pin=$5
    shift 5
    PORT=$((PORT + 1))
    openssl s_server -accept "$PORT" -naccept 1 -cert "$STATE/sc.pem" \
        -key "$STATE/sk.pem" -tls1_3 -www -quiet "$@" \
        >"$STATE/server.out" 2>&1 &
    sp=$!
    sleep 1
    set +e
    with_timeout 45 "$EMU" -c0 -r"$ROOT" /dis/sh.dis \
        /tests/brick/tls_client.sh /$REL "$profile" "$cert" "$pin" \
        "tcp!127.0.0.1!$PORT" >"$STATE/client.out" 2>&1
    clientrc=$?
    set -e
    kill "$sp" 2>/dev/null || true
    wait "$sp" 2>/dev/null || true
    sp=
    got=OTHER
    grep -q DATA-OK "$STATE/client.out" && got=DATA
    grep -q DATA-FAIL "$STATE/client.out" && got=DATAFAIL
    grep -q HANDSHAKE-FAIL "$STATE/client.out" && got=HSFAIL
    if emu_timeout_ok "$clientrc" && [ "$got" = "$expect" ]; then
        echo "PASS: $name ($got)"
    else
        echo "FAIL: $name (want $expect, got $got, emulator $clientrc)"
        sed 's/^/    /' "$STATE/client.out" "$STATE/server.out" 2>/dev/null
        fails=$((fails + 1))
    fi
}

VERIFY=-Verify
case_run cert-and-pin DATA /$REL/k - "$PIN" "$VERIFY" 1 -CAfile "$STATE/cc.pem"
case_run cert-and-pin-p256-chacha DATA /$REL/k - "$PIN" "$VERIFY" 1 \
    -CAfile "$STATE/cc.pem" -groups P-256 \
    -ciphersuites TLS_CHACHA20_POLY1305_SHA256
case_run no-cert-refused DATAFAIL - - "$PIN" "$VERIFY" 1 -CAfile "$STATE/cc.pem"
case_run wrong-pin-rejected HSFAIL /$REL/k - "$BADPIN" "$VERIFY" 1 -CAfile "$STATE/cc.pem"
case_run wrong-key-refused DATAFAIL /$REL/other /$REL/k/client.crt "$PIN" \
    "$VERIFY" 1 -CAfile "$STATE/cc.pem"
case_run pin-only DATA - - "$PIN"

echo "----"
if [ "$fails" -eq 0 ]; then
    echo "TLS client auth: ALL PASS"
    exit 0
fi
echo "TLS client auth: $fails FAILED"
exit 1
